SS_MSG(complete, EN("Output: {0}; written: {1}; unchanged photos: {3}; failed: {2}"), JA("出力: {0}; 保存: {1}; 元画像: {3}; 失敗: {2}"), ZH_HANS("输出：{0}；已写入：{1}；原始照片：{3}；失败：{2}"), ZH_HANT("輸出：{0}；已寫入：{1}；原始照片：{3}；失敗：{2}"), KO("출력: {0}; 저장: {1}; 원본 사진: {3}; 실패: {2}"), DE("Ausgabe: {0}; geschrieben: {1}; unveränderte Fotos: {3}; fehlgeschlagen: {2}"), FR("Sortie : {0} ; écrites : {1} ; photos inchangées : {3} ; échecs : {2}"), ES("Salida: {0}; escritas: {1}; fotos sin cambios: {3}; fallidas: {2}"), PT("Saída: {0}; gravadas: {1}; fotos inalteradas: {3}; falhas: {2}"), IT("Output: {0}; scritte: {1}; foto invariate: {3}; errori: {2}"), NL("Uitvoer: {0}; geschreven: {1}; ongewijzigde foto’s: {3}; mislukt: {2}"), RU("Вывод: {0}; записано: {1}; исходных фото: {3}; ошибок: {2}"), TR("Çıktı: {0}; yazılan: {1}; değişmeyen fotoğraflar: {3}; başarısız: {2}"));
